import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static int[] parent, sz;

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sz[a] += sz[b];
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] v = new int[n];
        int limit = 1;
        for (int i = 0; i < n; i++) {
            v[i] = nextInt();
            limit = Math.max(limit, v[i]);
        }
        // Smallest prime factor sieve.
        int[] spf = new int[limit + 1];
        for (int i = 0; i <= limit; i++) spf[i] = i;
        for (int p = 2; (long) p * p <= limit; p++)
            if (spf[p] == p)
                for (int m = p * p; m <= limit; m += p)
                    if (spf[m] == m) spf[m] = p;
        parent = new int[n];
        sz = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            sz[i] = 1;
        }
        // Union every server with the first server that had the same prime factor.
        int[] owner = new int[limit + 1];
        Arrays.fill(owner, -1);
        for (int i = 0; i < n; i++) {
            int x = v[i];
            while (x > 1) {
                int p = spf[x];
                if (owner[p] >= 0) unite(i, owner[p]);
                else owner[p] = i;
                while (x % p == 0) x /= p;
            }
        }
        int[] count = new int[n];
        for (int i = 0; i < n; i++) count[find(i)]++;
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(',');
            sb.append(count[find(i)]);
        }
        sb.append("]\n");
        System.out.print(sb);
    }
}
